argv:
$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-new-search-g1.mjs'
try {
[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({error:'hard_timeout'}));process.exit(0)},10500);
try{
const info=await(await fetch('http://127.0.0.1:17447/json/version')).json();
const w=new WebSocket(info.webSocketDebuggerUrl);
await new Promise((ok,no)=>{w.addEventListener('open',ok,{once:true});w.addEventListener('error',no,{once:true})});
let seq=0;const p=new Map();
w.addEventListener('message',e=>{const z=JSON.parse(e.data);if(p.has(z.id)){p.get(z.id)(z);p.delete(z.id)}});
const results=[];
for(const url of ["https://www.avito.ru/krasnoyarsk/telefony?q=iphone%2015%20pro%20max&sort=price","https://www.avito.ru/krasnoyarsk/telefony?q=iphone%2016%20pro%20max&sort=price"]){
 const z=await Promise.race([new Promise(ok=>{const id=++seq;p.set(id,ok);w.send(JSON.stringify({id,method:'Target.createTarget',params:{url,background:true,newWindow:false}}))}),new Promise(ok=>setTimeout(()=>ok({error:{message:'cdp_reply_timeout'}}),3500))]);
 results.push({url,target_id:z.result?.targetId||null,error:z.error?.message||null});
}
console.log(JSON.stringify({ok:true,results}));process.exit(0);
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,120)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false))
& node.exe $tmp
} finally { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
